import cn from 'classnames';
import { TeaserProps } from './teaser.types';
import './teaser.scss';

export function Teaser({
  id,
  title,
  titleTag = 'h2',
  alignContent,
  description,
  imagePath,
  pretitle,
  className,
  actions,
  link,
  styles,
  lineClamp,
  titleLinkHidden,
  actionsEnabled,
  date,
  video,
  lazyEnabled = true,
  imageFetchpriority = 'auto',
  imageSrcSet,
  imageDecoding = 'async',
  useJsModal = false,
}: TeaserProps) {
  const TitleTag = titleTag;

  const isLinked = titleLinkHidden === true && actionsEnabled === false && link && link.url;

  const teaserAlignedContent = cn({
    'content-center': alignContent === 'center',
    'content-right': alignContent === 'right',
  });
  const teaserLineClamp = cn({
    'teaser-line-clamp-1': lineClamp === '1',
    'teaser-line-clamp-2': lineClamp === '2',
    'teaser-line-clamp-3': lineClamp === '3',
    'teaser-line-clamp-4': lineClamp === '4',
    'teaser-line-clamp-5': lineClamp === '5',
  });

  const loading = lazyEnabled ? 'lazy' : undefined;

  const getTeaserBody = () => {
    return (
      <>
        <div className="cmp-teaser__content">
          {date && <p className="cmp-teaser__date">{date}</p>}
          {pretitle && <p className="cmp-teaser__pretitle">{pretitle}</p>}
          {title && (
            <TitleTag className="cmp-teaser__title">
              {!titleLinkHidden && link ? (
                <a href="/" className="cmp-teaser__title-link">
                  {title}
                </a>
              ) : (
                title
              )}
            </TitleTag>
          )}
          {description && (
            <div className="cmp-teaser__description" dangerouslySetInnerHTML={{ __html: description }}></div>
          )}
          {actionsEnabled && actions && actions.length ? (
            <div className="cmp-teaser__action-container">
              {actions.map((action) => (
                <a
                  key={action.id}
                  className={cn({ 'js-modal': useJsModal }, 'cmp-teaser__action-link')}
                  id={action.id}
                  data-cmp-data-layer=""
                  data-cmp-clickable=""
                  href={action.link?.url}
                  target={action.target}
                >
                  {action.title}
                </a>
              ))}
            </div>
          ) : null}
        </div>
        {imagePath && (
          <div className="cmp-teaser__image">
            <div id={id ? `${id}-image` : undefined} data-cmp-data-layer="" className="cmp-image">
              <img
                src={imagePath}
                srcSet={imageSrcSet}
                loading={loading}
                fetchpriority={imageFetchpriority}
                decoding={imageDecoding}
                className="cmp-image__image"
                itemProp="contentUrl"
                alt={title}
                title={title}
              />
              <meta itemProp="caption" content={title} />
            </div>
          </div>
        )}
        {video && (
          <div className="cmp-teaser__video">
            <div id={id ? `${id}-video` : undefined} className="cmp-video">
              <video
                {...(video.autoPlay && { autoPlay: true })}
                {...(video.controls && { controls: true })}
                {...(video.loop && { loop: true })}
                {...(video.muted && { muted: true })}
                {...(video.playsInline && { playsInline: true })}
                width={video.width}
                height={video.height}
                poster={video.poster}
                className="cmp-video__video"
              >
                {video.source
                  ? video.source.map((item) => <source key={item.id} src={item.url} type={item.type} />)
                  : null}
              </video>
            </div>
          </div>
        )}
      </>
    );
  };

  return (
    <div className={cn('teaser', [teaserAlignedContent, teaserLineClamp], className)} style={styles}>
      <div id={id} className="cmp-teaser" data-cmp-data-layer="">
        {!!isLinked ? (
          <a
            className={cn({ 'cmp-teaser__link': !useJsModal, 'js-modal cmp-teaser': useJsModal })}
            data-cmp-clickable=""
            href={link.url}
          >
            {getTeaserBody()}
          </a>
        ) : (
          getTeaserBody()
        )}
      </div>
    </div>
  );
}

export default Teaser;
